:host {
  /* the font custom properties are generated at build time */
  --font-overpass: 'SDM Overpass', system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
  --font-satoshi: 'SDM satoshi', system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
  --font-satoshi-medium: 'SDM satoshiMedium', system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
